{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rule lacks a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The RDP ingress rule has no description, making its purpose and intended source harder to identify during security reviews and incident response."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP is exposed to the public internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The rule permits TCP port 3389 from 0.0.0.0/0, exposing Windows RDP to internet-wide scanning, brute-force attempts, and exploitation."
    }
  ],
  "patched_code": "variable "allowed_rdp_cidr" {
  description = "Trusted IPv4 CIDR permitted to connect using RDP. Public /0 access is prohibited."
  type        = string

  validation {
    condition = (
      can(cidrnetmask(var.allowed_rdp_cidr)) &&
      can(regex("/([1-9]|[12][0-9]|3[0-2])$", var.allowed_rdp_cidr))
    )
    error_message = "allowed_rdp_cidr must be a valid IPv4 CIDR with a prefix length between 1 and 32."
  }
}

resource "aws_security_group_rule" "changeme_remote_exec_inline_security_group_rule_incoming_rdp" {
  description       = "Allow RDP access from the explicitly configured trusted IPv4 CIDR"
  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id
  type              = "ingress"
  from_port         = 3389
  to_port           = 3389
  protocol          = "tcp"
  cidr_blocks       = [var.allowed_rdp_cidr]
}
",
  "fix_summary": "Added a description to the RDP ingress rule and replaced unrestricted internet access with a required trusted IPv4 CIDR. Validation prevents configuring a /0 CIDR."
}
